"""Comprehensive tests for Boyer-Moore majority vote algorithm."""

import pytest
from majority_vote import majority_vote, majority_vote_brute


# ── Basic correctness ──────────────────────────────────────────────

class TestBasicMajority:
    def test_single_element(self):
        assert majority_vote([1]) == 1

    def test_two_same(self):
        assert majority_vote([7, 7]) == 7

    def test_two_different(self):
        assert majority_vote([1, 2]) is None

    def test_odd_length_majority(self):
        assert majority_vote([3, 3, 4, 2, 3, 3, 3, 2, 3]) == 3

    def test_even_length_majority(self):
        assert majority_vote([2, 2, 1, 1, 2, 2]) == 2

    def test_no_majority_even(self):
        assert majority_vote([1, 2, 3, 4]) is None

    def test_no_majority_odd(self):
        assert majority_vote([1, 2, 3]) is None

    def test_all_same(self):
        assert majority_vote([5, 5, 5, 5, 5]) == 5

    def test_majority_at_start(self):
        assert majority_vote([1, 1, 1, 2, 3]) == 1

    def test_majority_at_end(self):
        assert majority_vote([2, 3, 1, 1, 1]) == 1

    def test_majority_scattered(self):
        assert majority_vote([1, 2, 1, 3, 1, 4, 1]) == 1


# ── Edge cases ─────────────────────────────────────────────────────

class TestEdgeCases:
    def test_empty_list(self):
        assert majority_vote([]) is None

    def test_single_occurrence_bare_majority(self):
        # n=3, need >1.5 → 2 occurrences
        assert majority_vote([1, 1, 2]) == 1

    def test_exactly_half_not_majority(self):
        # n=4, need >2, only 2 → no majority
        assert majority_vote([1, 1, 2, 2]) is None

    def test_one_over_half(self):
        # n=5, need >2.5 → 3 occurrences
        assert majority_vote([1, 1, 1, 2, 3]) == 1

    def test_negative_numbers(self):
        assert majority_vote([-1, -1, -1, 2, 3]) == -1

    def test_zero_majority(self):
        assert majority_vote([0, 0, 0, 1]) == 0

    def test_large_values(self):
        big = 10**18
        assert majority_vote([big, big, big, 1]) == big


# ── Stress / large inputs ──────────────────────────────────────────

class TestLargeInputs:
    def test_large_with_majority(self):
        n = 10_000
        nums = [42] * (n // 2 + 1) + list(range(n // 2))
        assert majority_vote(nums) == 42

    def test_large_no_majority(self):
        # Alternating values → no majority
        nums = [i % 2 for i in range(10_000)]
        assert majority_vote(nums) is None

    def test_large_all_same(self):
        nums = [99] * 50_000
        assert majority_vote(nums) == 99


# ── Agreement with brute-force reference ────────────────────────────

class TestBruteForceAgreement:
    @pytest.mark.parametrize("nums", [
        [],
        [1],
        [1, 2],
        [1, 1],
        [1, 2, 3],
        [1, 1, 2],
        [1, 1, 1, 2],
        [1, 1, 2, 2],
        [3, 3, 4, 2, 3, 3, 3, 2, 3],
        [1, 2, 1, 3, 1, 4, 1],
        [5, 5, 5, 5, 5],
        [-1, -1, 0, 0, -1],
    ])
    def test_matches_brute_force(self, nums):
        assert majority_vote(nums) == majority_vote_brute(nums)
